previewCss:
.darma-loader-darma-b14-clothesline-sway { --accent: var(--loader-color, #38bdf8); --accent-2: var(--loader-secondary-color, #f8fafc); width: var(--loader-size, 120px); height: calc(var(--loader-size, 120px) * .74); position: relative; }
.darma-loader-darma-b14-clothesline-sway::before { content: ''; position: absolute; z-index: 2; top: 10%; left: 0; width: 100%; height: 18%; border-bottom: calc(var(--loader-size, 120px) * .022) solid color-mix(in srgb, #000 42%, var(--accent-2)); border-radius: 0 0 50% 50% / 0 0 100% 100%; }
.darma-loader-darma-b14-clothesline-sway span { position: absolute; width: 19%; height: 44%; transform-origin: top center; background: linear-gradient(var(--accent), var(--accent-2)); animation: darma-loader-darma-b14-clothesline-sway-sway calc(var(--loader-speed, 1s) * 2.2) ease-in-out infinite; }
.darma-loader-darma-b14-clothesline-sway span::after { content: ''; position: absolute; z-index: 3; bottom: 97%; left: 38%; width: 24%; height: calc(var(--loader-size, 120px) * .055); border-radius: 2px; background: color-mix(in srgb, #000 26%, var(--accent-2)); }
.darma-loader-darma-b14-clothesline-sway span:nth-child(1) { left: 4%; top: 25%; border-radius: 3px 3px 40% 8%; }
.darma-loader-darma-b14-clothesline-sway span:nth-child(2) { left: 28%; top: 30%; border-radius: 3px 3px 8% 40%; animation-delay: calc(var(--loader-speed, 1s) * .16); }
.darma-loader-darma-b14-clothesline-sway span:nth-child(3) { left: 52%; top: 30%; border-radius: 3px 3px 40% 8%; animation-delay: calc(var(--loader-speed, 1s) * .32); }
.darma-loader-darma-b14-clothesline-sway span:nth-child(4) { left: 76%; top: 25%; border-radius: 3px 3px 8% 40%; animation-delay: calc(var(--loader-speed, 1s) * .48); }
@keyframes darma-loader-darma-b14-clothesline-sway-sway { 0%, 100% { transform: rotate(-9deg); } 50% { transform: rotate(9deg); } }

